package cmd

import (
	"bytes"
	"testing"
)

// FuzzMatchedGeneratedCategory verifies two invariants of the marker-matching
// function under arbitrary input:
//
//  1. Any content without the "Code generated" prefix never matches.
//  2. Any match implies one of the three known category markers is present.
//
// The seed corpus doubles as a table-driven test when run with plain `go test`
// (no -fuzz flag required). Use `-fuzz=FuzzMatchedGeneratedCategory` to engage
// the fuzzing engine for deeper exploration.
func FuzzMatchedGeneratedCategory(f *testing.F) {
	f.Add([]byte("package main\nfunc main() {}"))
	f.Add([]byte("Code generated by templ. DO NOT EDIT."))
	f.Add([]byte("Code generated by sqlc. DO NOT EDIT."))
	f.Add([]byte("Code generated by protoc-gen-go. DO NOT EDIT."))
	f.Add([]byte("Code generated by unknown generator. DO NOT EDIT."))
	f.Add([]byte(""))

	f.Fuzz(func(t *testing.T, content []byte) {
		reason, matched := matchedGeneratedCategory(content)

		if !bytes.Contains(content, []byte(generatedHeader)) {
			if matched {
				t.Errorf("matched without %q header: content=%q reason=%s",
					generatedHeader, content, reason)
			}

			return
		}

		if matched {
			hasTempl := bytes.Contains(content, []byte(templMarker))
			hasSQLC := bytes.Contains(content, []byte(sqlcMarker))
			hasProtobuf := bytes.Contains(content, []byte(protobufMarker))

			if !hasTempl && !hasSQLC && !hasProtobuf {
				t.Errorf("matched without any known marker: content=%q reason=%s",
					content, reason)
			}
		}
	})
}
